-- ===== U5 vocab 覆盖灌库(volume='9',52词)。分步跑,每步贴回 count。=====

-- [step0] 灌前 count(应=DB现有U5骨架数)
SELECT 'U5 灌前' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U5';

-- [step1] DELETE 旧骨架(键 grade=9 volume='9' unit='U5')
DELETE FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U5';
SELECT 'U5 DELETE后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U5';  -- 应0

-- [step2] INSERT 官方 52 词(volume='9' + WHERE NOT EXISTS 防重)
SELECT 'U5 INSERT后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U5';  -- 应52

-- [查重] 应0行
SELECT word, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U5' GROUP BY word HAVING count(*)>1;